#!/usr/bin/env python3
"""2026-10-24: five independent, local-first, English-language web tools."""
from pathlib import Path
import json, html
ROOT=Path(__file__).resolve().parents[1]
CSS='''
:root{--ink:#123444;--muted:#55717c;--teal:#086d68;--line:#d8e7e4;--pale:#f4faf8}
*{box-sizing:border-box}body{margin:0;background:var(--pale);color:var(--ink);font:15px/1.55 system-ui,-apple-system,"Segoe UI",sans-serif}main.app{max-width:1160px;margin:0 auto;padding:30px 18px 55px}h1{font-size:clamp(30px,4.2vw,44px);line-height:1.12;letter-spacing:-1.2px;margin:9px 0}h2{font-size:21px;margin:0 0 14px}h3{font-size:16px;margin:12px 0 8px}.eyebrow{font-size:12px;font-weight:900;color:var(--teal);letter-spacing:1.4px;text-transform:uppercase}.lead{color:var(--muted);font-size:17px;max-width:780px}.grid{display:grid;grid-template-columns:minmax(0,1.05fr) minmax(300px,.95fr);gap:18px;align-items:start;margin-top:24px}.panel,.prose{background:white;border:1px solid var(--line);border-radius:17px;padding:22px;min-width:0;box-shadow:0 8px 24px #0a604006}.prose{margin-top:18px;box-shadow:none}.prose p,.prose li{color:#526d76}.fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.fields.three{grid-template-columns:repeat(3,minmax(0,1fr))}label{display:flex;flex-direction:column;gap:5px;color:#3b606b;font-size:13px;font-weight:750}input,select,textarea{width:100%;min-width:0;border:1px solid #b9cfca;border-radius:9px;padding:10px 11px;font:inherit;color:#163947;background:white}input:focus,select:focus,textarea:focus{outline:3px solid #c3eee4;border-color:var(--teal)}button{border:1px solid #b6d5ce;border-radius:9px;padding:10px 13px;background:#e8f6f2;color:#08695f;font:inherit;font-size:14px;font-weight:800;cursor:pointer}button.primary{background:var(--teal);color:white;border-color:var(--teal)}.actions{display:flex;gap:9px;flex-wrap:wrap;margin:16px 0}.metrics{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:11px}.metric{background:#eaf6f2;padding:13px;border-radius:11px}.metric small{display:block;color:#54727b}.metric strong{display:block;font-size:clamp(19px,2.5vw,27px);overflow-wrap:anywhere}.note{font-size:13px;color:#5c7580}.warning{background:#fff7e7;padding:13px;border-left:3px solid #cba45d;font-size:13px;margin-top:15px}.status{min-height:22px;font-size:13px;color:#0b706a}.row{border:1px solid var(--line);padding:12px;border-radius:11px;margin:10px 0}.rowhead{display:flex;justify-content:space-between;gap:10px;align-items:center}.rowhead strong{overflow-wrap:anywhere}.rowhead button{padding:5px 9px}.tablewrap{overflow:auto}table{border-collapse:collapse;width:100%;font-size:13px}th,td{border-bottom:1px solid var(--line);padding:9px;text-align:left}th{color:#496b74}.pill{display:inline-block;border-radius:99px;padding:4px 9px;background:#e8f6f2;color:#0a7068;font-size:12px;font-weight:750}.bad{color:#a94c33}.good{color:#007d61}.result-list{padding-left:22px}.result-list li{margin:8px 0}.full{grid-column:1/-1}@media(max-width:790px){.grid{grid-template-columns:1fr}}@media(max-width:480px){.fields,.fields.three{grid-template-columns:1fr}main.app{padding:22px 12px}.panel,.prose{padding:17px}}@media print{.actions,.eyebrow,.prose,.warning,.status,.no-print{display:none!important}.grid{display:block}.panel{box-shadow:none;border:0}}
'''
UTIL='''
const $=id=>document.getElementById(id), num=id=>Number($(id).value), money=v=>Number(v).toLocaleString('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}), clamp=(v,min=0,max=1e9)=>Math.min(max,Math.max(min,Number(v)||0));
function csv(rows){return '\\ufeff'+rows.map(r=>r.map(x=>'"'+String(x??'').replaceAll('"','""')+'"').join(',')).join('\\r\\n')}
function saveFile(data,name,type='text/csv;charset=utf-8'){let url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),7000)}
function status(msg){$('status').textContent=msg}
function dateToICS(d){return d.replaceAll('-','')}
function icsEscape(s){return String(s).replaceAll('\\\\','\\\\\\\\').replaceAll(';','\\\\;').replaceAll(',','\\\\,').replaceAll('\\n','\\\\n')}
function localGet(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
function localPut(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true}catch{status('Storage unavailable; please export your work.');return false}}
'''
def page(slug,name,headline,description,lead,content,script,explainer,faq):
    metadata={'@context':'https://schema.org','@type':'SoftwareApplication','name':name,'applicationCategory':'BusinessApplication','operatingSystem':'Web','description':description,'offers':{'@type':'Offer','price':'0','priceCurrency':'USD'}}
    src=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(headline)} | Worklane Tools</title><meta name="description" content="{html.escape(description,quote=True)}"><meta property="og:title" content="{html.escape(headline,quote=True)}"><meta property="og:description" content="{html.escape(description,quote=True)}"><meta property="og:type" content="website"><script type="application/ld+json">{json.dumps(metadata,ensure_ascii=False)}</script><style>{CSS}</style></head><body><main class="app"><div class="eyebrow">Free browser tool · No account required</div><h1>{html.escape(headline)}</h1><p class="lead">{html.escape(lead)}</p>{content}<section class="prose"><h2>What this calculator helps you decide</h2>{explainer}<h3>{html.escape(faq[0])}</h3><p>{html.escape(faq[1])}</p></section></main><script>{UTIL}\n{script}</script></body></html>'''
    dest=ROOT/'apps'/slug;dest.mkdir(parents=True,exist_ok=True);(dest/'index.html').write_text(src,encoding='utf-8')
    print('wrote',slug,len(src))

page('fencebid','FenceBid','Fence Installation Estimate Calculator with Gates','Estimate multi-run fence panel counts, gate openings, approximate posts, labor and material costs. Export a contractor planning worksheet.','Plan multiple fence runs, account for gate openings and calculate an editable, itemized preliminary quote.', '''<div class="grid"><section class="panel"><h2>Fence runs</h2><div id="runs"></div><div class="actions"><button id="add">+ Add fence run</button></div><div class="fields"><label>Maximum panel span (ft)<input id="span" type="number" min="1" step=".5" value="8"></label><label>Material per panel ($)<input id="panelPrice" type="number" min="0" value="95"></label><label>Post cost ($)<input id="postPrice" type="number" min="0" value="38"></label><label>Gate hardware and materials per gate ($)<input id="gatePrice" type="number" min="0" value="220"></label><label>Labor per linear foot ($)<input id="labor" type="number" min="0" value="18"></label><label>Contingency (%)<input id="contingency" type="number" min="0" max="100" value="10"></label></div><div class="actions"><button class="primary" id="export">Download itemized CSV</button><button id="print">Print estimate</button></div><p id="status" class="status" role="status"></p></section><section class="panel"><h2>Preliminary estimate</h2><div class="metrics"><div class="metric"><small>Fence length</small><strong id="length">—</strong></div><div class="metric"><small>Approx. panels</small><strong id="panels">—</strong></div><div class="metric"><small>Approx. posts</small><strong id="posts">—</strong></div><div class="metric"><small>Total estimated cost</small><strong id="total">—</strong></div></div><div id="detail" class="tablewrap"></div><p class="warning">Planning estimate only. Post locations, corner/end posts, gate supports, slopes, soil, footing depth, permits and code requirements need a site-specific takeoff. Do not order materials from this estimate alone.</p></section></div>''', '''
let runs=[{name:'Backyard',length:90,gates:1,gateWidth:4},{name:'Side yard',length:34,gates:0,gateWidth:4}];let last={};
function draw(){let root=$('runs');root.innerHTML='';runs.forEach((r,i)=>{let e=document.createElement('div');e.className='row';e.innerHTML=`<div class="rowhead"><strong>Run ${i+1}</strong><button type="button" data-remove="${i}" aria-label="Remove run ${i+1}">Remove</button></div><div class="fields"><label>Run name<input data-i="${i}" data-k="name" maxlength="65"></label><label>Length (ft)<input type="number" min="0" step=".1" data-i="${i}" data-k="length"></label><label>Number of gates<input type="number" min="0" step="1" data-i="${i}" data-k="gates"></label><label>Width of each gate (ft)<input type="number" min="0" step=".1" data-i="${i}" data-k="gateWidth"></label></div>`;root.append(e);for(let key of Object.keys(r)){e.querySelector(`[data-k="${key}"]`).value=r[key]}});render()}
function render(){let span=num('span'),panelPrice=num('panelPrice'),postPrice=num('postPrice'),gatePrice=num('gatePrice'),labor=num('labor'),cont=num('contingency');let valid=[span,panelPrice,postPrice,gatePrice,labor,cont].every(Number.isFinite)&&span>0&&[panelPrice,postPrice,gatePrice,labor,cont].every(x=>x>=0)&&cont<=100;let totals={length:0,panels:0,posts:0,gates:0,material:0,labor:0};let breakdown=[];for(let r of runs){let len=Number(r.length),g=Number(r.gates),w=Number(r.gateWidth);if(![len,g,w].every(Number.isFinite)||len<0||g<0||!Number.isInteger(g)||w<0||g*w>=len&&len>0||len===0){valid=false;break}let panels=Math.ceil((len-g*w)/span),posts=panels+1+g;totals.length+=len;totals.panels+=panels;totals.posts+=posts;totals.gates+=g;breakdown.push([r.name,len,g,panels,posts]);}
if(!valid){status('Check lengths, gates and prices. Each run must have positive length and gate openings smaller than the run.');$('total').textContent='—';return}
totals.material=totals.panels*panelPrice+totals.posts*postPrice+totals.gates*gatePrice;totals.labor=totals.length*labor;totals.total=(totals.material+totals.labor)*(1+cont/100);last={...totals,breakdown,cont};$('length').textContent=totals.length.toFixed(1)+' ft';$('panels').textContent=totals.panels;$('posts').textContent=totals.posts;$('total').textContent=money(totals.total);$('detail').innerHTML=`<table><tbody><tr><th>Material + gate hardware</th><td>${money(totals.material)}</td></tr><tr><th>Labor</th><td>${money(totals.labor)}</td></tr><tr><th>Contingency</th><td>${money(totals.total-totals.material-totals.labor)}</td></tr></tbody></table>`;status('');}
$('runs').addEventListener('input',e=>{let t=e.target;if(t.dataset.k){runs[Number(t.dataset.i)][t.dataset.k]=t.dataset.k==='name'?t.value:Number(t.value);render()}});$('runs').addEventListener('click',e=>{let b=e.target.closest('[data-remove]');if(b){runs.splice(Number(b.dataset.remove),1);draw()}});$('add').onclick=()=>{runs.push({name:'New run',length:24,gates:0,gateWidth:4});draw()};['span','panelPrice','postPrice','gatePrice','labor','contingency'].forEach(k=>$(k).addEventListener('input',render));$('export').onclick=()=>{render();if(!last.breakdown)return;saveFile(csv([['run','length_ft','gates','approx_panels','approx_posts'],...last.breakdown,['TOTAL',last.length,last.gates,last.panels,last.posts],['estimated_materials',last.material],['estimated_labor',last.labor],['estimated_cost_with_contingency',last.total]]),'fencebid-estimate.csv')};$('print').onclick=()=>window.print();draw();
''','''<p>FenceBid treats each run separately and subtracts gate openings from the length that needs panels. The approximate post count is the number of panel spans plus one per run and one additional boundary per gate opening. This is a planning convention, not an engineering design.</p><p>Use your own material, labor and contingency prices. Actual layout depends on where gates and corners fall, whether runs share posts, local installation standards, and terrain. The export provides an auditable starting point for an on-site estimate.</p>''',('Will it calculate the exact number of fence posts?','No. It estimates posts from spans and gate openings. Verify actual corner, terminal, gate and shared-post placement on site.'))

page('mulchcompare','MulchCompare','Bulk Mulch vs Bags Cost Calculator for Multiple Beds','Compare mulch bags with bulk delivery using multiple garden beds, depth, bag size, waste allowance, local prices and delivery fees.','Add every bed, choose a depth, then see cubic yards, bag count and delivered cost side by side.', '''<div class="grid"><section class="panel"><h2>Garden beds</h2><div id="beds"></div><div class="actions"><button id="add">+ Add bed</button></div><div class="fields"><label>Extra material (%)<input id="extra" type="number" min="0" max="100" value="10"></label><label>Bag size (cubic ft)<input id="bagSize" type="number" min=".1" step=".1" value="2"></label><label>Price per bag ($)<input id="bagPrice" type="number" min="0" step=".01" value="5.50"></label><label>Bulk price per cubic yard ($)<input id="yardPrice" type="number" min="0" value="38"></label><label>Bulk delivery fee ($)<input id="delivery" type="number" min="0" value="75"></label><label>Bulk order increment (yards)<select id="increment"><option value="0.25">0.25 yard</option><option value="0.5">0.5 yard</option><option value="1">1 yard</option></select></label></div><div class="actions"><button id="export" class="primary">Export comparison CSV</button><button id="print">Print comparison</button></div><p id="status" class="status" role="status"></p></section><section class="panel"><h2>Order comparison</h2><div class="metrics"><div class="metric"><small>Volume needed</small><strong id="volume">—</strong></div><div class="metric"><small>2 cu ft equivalent bags</small><strong id="bags">—</strong></div><div class="metric"><small>Bag purchase total</small><strong id="bagTotal">—</strong></div><div class="metric"><small>Bulk delivered total</small><strong id="bulkTotal">—</strong></div></div><h3 id="winner"></h3><p id="explain" class="note"></p><p class="warning">Delivery minimums, taxes, installation labor, access and actual bag coverage are not included unless you adjust your inputs. Use product-specific depth guidance.</p></section></div>''', '''
let beds=[{name:'Front bed',length:24,width:5,depth:3},{name:'Side bed',length:16,width:3,depth:2}];let result={};function draw(){let root=$('beds');root.innerHTML='';beds.forEach((r,i)=>{let e=document.createElement('div');e.className='row';e.innerHTML=`<div class="rowhead"><strong>Bed ${i+1}</strong><button data-remove="${i}" type="button">Remove</button></div><div class="fields"><label>Bed name<input data-i="${i}" data-k="name" maxlength="65"></label><label>Length (ft)<input type="number" min="0" step=".1" data-i="${i}" data-k="length"></label><label>Width (ft)<input type="number" min="0" step=".1" data-i="${i}" data-k="width"></label><label>Depth (inches)<input type="number" min="0" step=".25" data-i="${i}" data-k="depth"></label></div>`;root.append(e);for(let k in r)e.querySelector(`[data-k="${k}"]`).value=r[k]});render()}
function render(){let inputs=['extra','bagSize','bagPrice','yardPrice','delivery'].map(num),[extra,bagSize,bagPrice,yardPrice,delivery]=inputs,inc=num('increment');let valid=inputs.every(x=>Number.isFinite(x)&&x>=0)&&extra<=100&&bagSize>0;let volume=0;for(let b of beds){let v=[b.length,b.width,b.depth].map(Number);if(!v.every(x=>Number.isFinite(x)&&x>0)){valid=false;break}volume+=v[0]*v[1]*v[2]/12}if(!valid){status('Enter positive bed dimensions and valid nonnegative prices.');$('volume').textContent='—';return}volume*=1+extra/100;let yards=volume/27,bags=Math.ceil(volume/bagSize),bulkYards=Math.ceil(yards/inc)*inc,bagTotal=bags*bagPrice,bulkTotal=bulkYards*yardPrice+delivery;result={yards,bags,bulkYards,bagTotal,bulkTotal,volume};$('volume').textContent=yards.toFixed(2)+' yd³';$('bags').textContent=bags;$('bagTotal').textContent=money(bagTotal);$('bulkTotal').textContent=money(bulkTotal);$('winner').textContent=bagTotal<bulkTotal?'Bags are cheaper by '+money(bulkTotal-bagTotal):bagTotal>bulkTotal?'Bulk is cheaper by '+money(bagTotal-bulkTotal):'Both options cost the same';$('explain').textContent=`Bulk order rounded up to ${bulkYards.toFixed(2)} cubic yards. Bag count rounded up to whole ${bagSize} cu ft bags.`;status('');}
$('beds').addEventListener('input',e=>{let t=e.target;if(t.dataset.k){beds[Number(t.dataset.i)][t.dataset.k]=t.dataset.k==='name'?t.value:Number(t.value);render()}});$('beds').addEventListener('click',e=>{let b=e.target.closest('[data-remove]');if(b){beds.splice(Number(b.dataset.remove),1);draw()}});$('add').onclick=()=>{beds.push({name:'New bed',length:10,width:5,depth:3});draw()};['extra','bagSize','bagPrice','yardPrice','delivery','increment'].forEach(k=>$(k).addEventListener('input',render));$('export').onclick=()=>{render();if(!result.volume)return;saveFile(csv([['bed','length_ft','width_ft','depth_in'],...beds.map(b=>[b.name,b.length,b.width,b.depth]),['cubic_yards_needed',result.yards],['bags_needed',result.bags],['bulk_order_yards',result.bulkYards],['bag_cost',result.bagTotal],['bulk_delivered_cost',result.bulkTotal]]),'mulchcompare.csv')};$('print').onclick=()=>window.print();draw();
''','''<p>Buying mulch by the bag can be convenient for a small garden, while bulk delivery may become cheaper as volume grows. MulchCompare converts each rectangular bed from square feet and depth to cubic feet, then to cubic yards. It rounds bags and bulk quantities to your selected purchase units.</p><p>Compare the full delivered cost rather than only the price per cubic yard. Product coverage varies with mulch texture, compaction and depth; measure irregular beds in smaller rectangles for a closer estimate.</p>''',('Can I compare two-cubic-foot bags with bulk mulch?','Yes. Change the bag size, price, bulk yard price and delivery fee to match quotes from local suppliers.'))

page('weddingflow','WeddingFlow','Wedding Photography Timeline Planner with Coverage Check','Build a photography-specific wedding-day schedule around ceremony time, portraits, family photos and travel; export calendar events.','Set the ceremony anchor and the time you need for each photography block. Check coverage before sending a plan to your couple.', '''<div class="grid"><section class="panel"><h2>Photography schedule settings</h2><div class="fields"><label>Wedding date<input id="date" type="date" value="2026-11-14"></label><label>Ceremony begins<input id="ceremony" type="time" value="16:00"></label><label>Coverage start<input id="start" type="time" value="12:00"></label><label>Booked coverage (hours)<input id="coverage" type="number" min="1" max="20" step=".5" value="8"></label><label>Getting ready photos (min)<input id="getting" type="number" min="0" value="45"></label><label>First look (min)<input id="first" type="number" min="0" value="20"></label><label>Wedding party portraits (min)<input id="party" type="number" min="0" value="35"></label><label>Pre-ceremony buffer (min)<input id="buffer" type="number" min="0" value="20"></label><label>Ceremony duration (min)<input id="ceremonyDur" type="number" min="0" value="35"></label><label>Family photos after ceremony (min)<input id="family" type="number" min="0" value="30"></label><label>Couple portraits (min)<input id="couple" type="number" min="0" value="25"></label><label>Reception coverage (min)<input id="reception" type="number" min="0" value="100"></label></div><div class="actions"><button class="primary" id="ics">Download calendar ICS</button><button id="csv">Export schedule CSV</button><button id="print">Print timeline</button></div><p id="status" class="status" role="status"></p></section><section class="panel"><h2>Suggested timeline</h2><div class="metrics"><div class="metric"><small>First planned block</small><strong id="firstTime">—</strong></div><div class="metric"><small>Last planned block ends</small><strong id="lastTime">—</strong></div></div><p id="coverageStatus" class="warning"></p><ol id="timeline" class="result-list"></ol><p class="note">Times are relative to the ceremony. Edit every duration to match the venue, people and actual travel distances.</p></section></div>''', '''
const ids=['date','ceremony','start','coverage','getting','first','party','buffer','ceremonyDur','family','couple','reception'];let blocks=[];function mins(s){let a=s.split(':').map(Number);return a[0]*60+a[1]}function fmt(m){let day=Math.floor(m/1440),t=((m%1440)+1440)%1440,h=Math.floor(t/60),mm=t%60;return `${String(h).padStart(2,'0')}:${String(mm).padStart(2,'0')}${day<0?' (previous day)':day>0?' (next day)':''}`}
function render(){let date=$('date').value,cer=mins($('ceremony').value),start=mins($('start').value),coverage=num('coverage'),v=['getting','first','party','buffer','ceremonyDur','family','couple','reception'].map(num);if(!date||!v.every(x=>Number.isFinite(x)&&x>=0&&x<=720)||!Number.isFinite(coverage)||coverage<=0){status('Choose a date, valid durations and coverage hours.');return}let pre=[['Getting ready photos',v[0]],['First look',v[1]],['Wedding party portraits',v[2]],['Buffer / travel before ceremony',v[3]]],preTotal=pre.reduce((s,x)=>s+x[1],0),cursor=cer-preTotal;blocks=[];for(let [name,duration] of pre){if(duration>0){blocks.push({name,start:cursor,end:cursor+duration});cursor+=duration}}let post=[['Ceremony',v[4]],['Family group photos',v[5]],['Couple portraits',v[6]],['Reception coverage',v[7]]];cursor=cer;for(let [name,duration] of post){if(duration>0){blocks.push({name,start:cursor,end:cursor+duration});cursor+=duration}}let first=blocks.length?blocks[0].start:cer,last=blocks.length?blocks[blocks.length-1].end:cer,end=start+coverage*60;$('firstTime').textContent=fmt(first);$('lastTime').textContent=fmt(last);$('coverageStatus').textContent=(first<start||last>end)?`Coverage conflict: planned blocks run ${fmt(first)}–${fmt(last)}, but booked coverage is ${fmt(start)}–${fmt(end)}. Adjust durations or coverage.`:`All planned blocks fit within ${coverage} hours of coverage (${fmt(start)}–${fmt(end)}).`;let list=$('timeline');list.replaceChildren();for(let b of blocks){let li=document.createElement('li');li.textContent=`${fmt(b.start)}–${fmt(b.end)} · ${b.name}`;list.append(li)}status('')}
ids.forEach(id=>$(id).addEventListener('input',render));$('csv').onclick=()=>{render();saveFile(csv([['event','start_local','end_local'],...blocks.map(b=>[b.name,fmt(b.start),fmt(b.end)])]),'wedding-photography-timeline.csv')};$('print').onclick=()=>window.print();$('ics').onclick=()=>{render();let date=$('date').value;if(!date||!blocks.length)return;let origin=new Date(date+'T00:00:00');let stamp=(m)=>{let d=new Date(origin.getTime()+m*60000);return d.getFullYear()+String(d.getMonth()+1).padStart(2,'0')+String(d.getDate()).padStart(2,'0')+'T'+String(d.getHours()).padStart(2,'0')+String(d.getMinutes()).padStart(2,'0')+'00'};let out=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Worklane Tools//WeddingFlow//EN','CALSCALE:GREGORIAN'];blocks.forEach((b,i)=>out.push('BEGIN:VEVENT',`UID:weddingflow-${date}-${i}@worklane.local`,`DTSTAMP:${new Date().toISOString().replace(/[-:]/g,'').replace(/\\.\\d{3}/,'')}`,`DTSTART:${stamp(b.start)}`,`DTEND:${stamp(b.end)}`,`SUMMARY:${icsEscape(b.name)}`,'END:VEVENT'));out.push('END:VCALENDAR');saveFile(out.join('\\r\\n'),'wedding-photography-timeline.ics','text/calendar;charset=utf-8');status('Calendar downloaded. Verify timezone after importing.')};render();
''','''<p>Photographers often create a separate photography plan alongside the coordinator's event schedule. WeddingFlow works backward from ceremony time to allocate getting-ready, first-look and wedding-party portraits, then forward through ceremony, family portraits, couple portraits and reception.</p><p>Coverage warnings flag blocks outside booked hours. Calendar exports use local date and time without an explicit timezone; confirm imported event times with the couple and planner. Real travel, weather, lighting and family group size can require substantial extra buffers.</p>''',('Does this replace the wedding coordinator’s timeline?','No. It is a photographer-specific planning draft. Confirm ceremony timing, travel, venue rules, sunset and all dependencies with the couple and coordinator.'))

page('turnoverbudget','TurnoverBudget','Rental Turnover Cost and Vacancy Loss Calculator','Plan rental make-ready costs and vacant days between tenants, track estimates versus actual spending and export a turnover budget.','Understand the full cost of getting a vacant rental ready, including lost rent—not tenant deposit deductions.', '''<div class="grid"><section class="panel"><h2>Property and vacancy</h2><div class="fields"><label>Property label<input id="property" maxlength="90" value="Unit 2B"></label><label>Monthly rent ($)<input id="rent" type="number" min="0" value="1800"></label><label>Expected vacant days<input id="days" type="number" min="0" value="18"></label><label>Actual vacant days<input id="actualDays" type="number" min="0" value="22"></label></div><h3>Make-ready expenses</h3><div id="items"></div><div class="actions"><button id="add">+ Add expense</button><button id="export" class="primary">Export turnover CSV</button><button id="print">Print budget</button></div><p id="status" class="status" role="status"></p></section><section class="panel"><h2>Turnover economics</h2><div class="metrics"><div class="metric"><small>Planned total incl. vacancy</small><strong id="planned">—</strong></div><div class="metric"><small>Actual total incl. vacancy</small><strong id="actual">—</strong></div><div class="metric"><small>Planned vacancy loss</small><strong id="plannedLoss">—</strong></div><div class="metric"><small>Actual vacancy loss</small><strong id="actualLoss">—</strong></div></div><h3 id="delta"></h3><div id="breakdown" class="tablewrap"></div><p class="warning">This is an owner budgeting worksheet, not a security deposit deduction statement. Normal wear, tenant charges and legal notice requirements vary by jurisdiction; do not infer chargeability from this budget.</p></section></div>''', '''
const key='worklane_turnoverbudget_v1';let items=localGet(key,[{name:'Deep cleaning',estimate:250,actual:270},{name:'Touch-up paint',estimate:400,actual:500},{name:'Lock rekey',estimate:120,actual:110}]);let result={};function draw(){let root=$('items');root.innerHTML='';items.forEach((r,i)=>{let e=document.createElement('div');e.className='row';e.innerHTML=`<div class="rowhead"><strong>Expense ${i+1}</strong><button type="button" data-remove="${i}">Remove</button></div><div class="fields"><label>Work item<input data-i="${i}" data-k="name" maxlength="90"></label><label>Estimated cost ($)<input type="number" min="0" data-i="${i}" data-k="estimate"></label><label>Actual cost ($)<input type="number" min="0" data-i="${i}" data-k="actual"></label></div>`;root.append(e);for(let k in r)e.querySelector(`[data-k="${k}"]`).value=r[k]});render()}
function render(){let rent=num('rent'),days=num('days'),actualDays=num('actualDays');let valid=[rent,days,actualDays].every(x=>Number.isFinite(x)&&x>=0);let est=0,act=0;for(let x of items){let a=Number(x.estimate),b=Number(x.actual);if(!Number.isFinite(a)||!Number.isFinite(b)||a<0||b<0){valid=false;break}est+=a;act+=b}if(!valid){status('Use nonnegative amounts and vacancy days.');return}let plannedLoss=rent/30*days,actualLoss=rent/30*actualDays,planned=est+plannedLoss,actual=act+actualLoss;result={rent,days,actualDays,plannedLoss,actualLoss,planned,actual,est,act};$('planned').textContent=money(planned);$('actual').textContent=money(actual);$('plannedLoss').textContent=money(plannedLoss);$('actualLoss').textContent=money(actualLoss);$('delta').textContent=actual>planned?'Over budget by '+money(actual-planned):actual<planned?'Under budget by '+money(planned-actual):'On budget';$('breakdown').innerHTML=`<table><thead><tr><th>Category</th><th>Planned</th><th>Actual</th></tr></thead><tbody><tr><td>Repairs and cleaning</td><td>${money(est)}</td><td>${money(act)}</td></tr><tr><td>Vacancy loss</td><td>${money(plannedLoss)}</td><td>${money(actualLoss)}</td></tr></tbody></table>`;localPut(key,items);status('Saved expense rows on this device. Export for backup.')}
$('items').addEventListener('input',e=>{let t=e.target;if(t.dataset.k){items[Number(t.dataset.i)][t.dataset.k]=t.dataset.k==='name'?t.value:Number(t.value);render()}});$('items').addEventListener('click',e=>{let b=e.target.closest('[data-remove]');if(b){items.splice(Number(b.dataset.remove),1);draw()}});$('add').onclick=()=>{items.push({name:'New expense',estimate:0,actual:0});draw()};['rent','days','actualDays'].forEach(k=>$(k).addEventListener('input',render));$('export').onclick=()=>{render();if(!result.planned&&result.planned!==0)return;saveFile(csv([['property',$('property').value],['monthly_rent',result.rent],['planned_vacancy_days',result.days],['actual_vacancy_days',result.actualDays],['item','estimated','actual'],...items.map(x=>[x.name,x.estimate,x.actual]),['planned_vacancy_loss',result.plannedLoss],['actual_vacancy_loss',result.actualLoss],['planned_total',result.planned],['actual_total',result.actual]]),'rental-turnover-budget.csv')};$('print').onclick=()=>window.print();draw();
''','''<p>Between tenants, owners may spend money on cleaning, painting, rekeying, repairs and utilities while also losing rent during vacancy. TurnoverBudget separates these owner costs from tenant security-deposit deductions. It uses a simple 30-day monthly-rent convention to estimate vacancy loss, not a legally required proration formula.</p><p>Compare expected costs with actual expenses, then export a record for your property budget. The tool stores expense rows only on your device and does not automatically save receipts or photos.</p>''',('Can I charge all turnover expenses to the former tenant?','No. This is a property-owner budget. Whether a specific cost can be charged to a tenant depends on the lease, local law, ordinary wear and supporting evidence.'))

page('feenet','FeeNet','Credit Card Processing Fee and Net Revenue Calculator','Compare payment processing fee structures and calculate net receipts or the gross amount needed to reach a target net revenue.','Model per-transaction fees and percentage rates before setting your small-business prices.', '''<div class="grid"><section class="panel"><h2>Sales assumptions</h2><div class="fields"><label>Gross sales ($)<input id="gross" type="number" min="0" value="10000"></label><label>Number of transactions<input id="transactions" type="number" min="1" step="1" value="100"></label><label>Target net receipts ($)<input id="target" type="number" min="0" value="10000"></label></div><h3>Compare two fee structures</h3><div class="row"><strong>Processor A</strong><div class="fields"><label>Label<input id="labelA" maxlength="60" value="Online card"></label><label>Rate (%)<input id="rateA" type="number" min="0" max="99" step=".1" value="3.3"></label><label>Fixed fee / transaction ($)<input id="fixedA" type="number" min="0" step=".01" value="0.30"></label></div></div><div class="row"><strong>Processor B</strong><div class="fields"><label>Label<input id="labelB" maxlength="60" value="In-person card"></label><label>Rate (%)<input id="rateB" type="number" min="0" max="99" step=".1" value="2.6"></label><label>Fixed fee / transaction ($)<input id="fixedB" type="number" min="0" step=".01" value="0.15"></label></div></div><div class="actions"><button class="primary" id="export">Download fee comparison CSV</button><button id="print">Print summary</button></div><p id="status" class="status" role="status"></p></section><section class="panel"><h2>Net receipts comparison</h2><div class="tablewrap" id="comparison"></div><h3 id="winner"></h3><p class="note" id="formula"></p><p class="warning">Fees are editable assumptions, not live processor quotes. Real fees can include tax, international cards, chargebacks, refunds, subscriptions and other costs. This tool does not recommend imposing a card surcharge; laws and card-network rules vary.</p></section></div>''', '''
let result=[];function render(){let gross=num('gross'),n=num('transactions'),target=num('target'),rates=[num('rateA'),num('rateB')],fixed=[num('fixedA'),num('fixedB')],labels=[$('labelA').value.trim()||'Processor A',$('labelB').value.trim()||'Processor B'];if(![gross,n,target,...rates,...fixed].every(x=>Number.isFinite(x)&&x>=0)||!Number.isInteger(n)||n<1||rates.some(x=>x>=100)){status('Use nonnegative values, a positive whole-number transaction count and rates below 100%.');$('comparison').textContent='';return}result=rates.map((rate,i)=>{let fees=gross*rate/100+n*fixed[i],net=gross-fees,grossRequired=(target+n*fixed[i])/(1-rate/100);return{label:labels[i],rate,fixed:fixed[i],fees,net,grossRequired}});let table=document.createElement('table');table.innerHTML='<thead><tr><th>Measure</th><th>Processor A</th><th>Processor B</th></tr></thead>';let body=document.createElement('tbody');for(let [label,key] of [['Processing fees','fees'],['Net receipts','net'],['Gross for target net','grossRequired']]){let tr=document.createElement('tr');for(let text of [label,money(result[0][key]),money(result[1][key])]){let td=document.createElement('td');td.textContent=text;tr.append(td)}body.append(tr)}table.append(body);$('comparison').replaceChildren(table);let winner=result[0].fees<result[1].fees?result[0]:result[1].fees<result[0].fees?result[1]:null;$('winner').textContent=winner?`${winner.label} costs ${money(Math.abs(result[0].fees-result[1].fees))} less at this volume.`:'Equal fees at this volume.';$('formula').textContent='Fees = gross sales × percentage + transaction count × fixed fee. Target gross = (target net + fixed fees) ÷ (1 − rate).';status('')}
['gross','transactions','target','rateA','rateB','fixedA','fixedB','labelA','labelB'].forEach(k=>$(k).addEventListener('input',render));$('export').onclick=()=>{render();if(result.length!==2)return;saveFile(csv([['processor','rate_pct','fixed_per_transaction','gross_sales','transaction_count','total_fees','net_receipts','gross_needed_for_target'],...result.map(x=>[x.label,x.rate,x.fixed,num('gross'),num('transactions'),x.fees,x.net,x.grossRequired])]),'payment-processing-fee-comparison.csv')};$('print').onclick=()=>window.print();render();
''','''<p>A 3% processing rate is not always the full cost of accepting cards. A fixed fee on every transaction matters especially for many small sales. FeeNet combines percentage and fixed charges to show total fees and the amount deposited before any other business expenses.</p><p>Use your processor's actual contracted rates. The reverse calculation estimates the gross revenue required to reach a desired net receipt level for the specified number of transactions. It is an internal planning calculation, not a legal determination of whether fees can be passed to customers.</p>''',('Does this show the actual current fees charged by Square or Stripe?','No. The initial values are editable examples. Verify your own merchant plan, transaction type and country-specific fees before relying on the result.'))

