cat_path=ROOT/'content/catalog.json';history_path=ROOT/'content/history.json'
cat=json.loads(cat_path.read_text(encoding='utf-8'));hist=json.loads(history_path.read_text(encoding='utf-8'))
old_slugs={t['slug'] for t in cat['tools']};hist_slugs={e['slug'] for e in hist['entries']}
assert len(old_slugs)==30 and len(hist_slugs)==30,(len(old_slugs),len(hist_slugs))
for e in entries:
    slug,name,aud,category,emoji,headline,description,keywords,best,howto,limits,fq,fa=e
    assert slug not in old_slugs and slug not in hist_slugs
    cat['tools'].append({'slug':slug,'name':name,'audience':aud,'category':category,'emoji':emoji,'headline':headline,'description':description,'keywords':keywords,'best_for':best,'howto':howto,'limitations':limits,'faq_question':fq,'faq_answer':fa,'approved_for_index':False,'evidence_reviewed':False,'qa_verified':False,'seed_from':'2026-10-24'})
    hist['entries'].append({'slug':slug,'date':'2026-10-24','problem':{'fencebid':'fence installation run and gate opening estimating','mulchcompare':'bag versus bulk mulch order cost across multiple garden beds','weddingflow':'wedding photographer ceremony anchored schedule and coverage conflict','turnoverbudget':'landlord unit turnover repairs cleaning and vacancy owner cost budget','feenet':'merchant card payment fee structure net receipts comparison'}[slug],'audience':category})
cat_path.write_text(json.dumps(cat,ensure_ascii=False,indent=2)+'\n',encoding='utf-8');history_path.write_text(json.dumps(hist,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print('catalog/history total',len(cat['tools']),len(hist['entries']))
